var IDLE = 0;
var RUNNING = 1;
var JUMPING = 2;

var MIN_JUMP = -13;
var MAX_JUMP = 12;
var JUMP_LENGTH = 78;
var MOVE_SPEED = 4;


var playerAnims = [];
var playerAnimators = []
playerAnims[0] = new MultipleAnimation('GFX/Player1.png', 3, 1, 60, 52);
playerAnims[1] = new MultipleAnimation('GFX/Player2.png', 3, 1, 60, 52);

for (var i = 0; i < playerAnims.length; i++) {
