    playerAnims[i].animations.push({ from: 0, to: 1, direction: 1, nextAnim: null });
    playerAnims[i].animations.push({ from: 2, to: 2, direction: 1, nextAnim: null });
    playerAnimators[i] = new MultipleAnimator(playerAnims[i], 0, 0, 40);
}

function Player(animator, x, y, controll, fromX, toX, leftKey, rightKey, jumpKey) {
    this.point = new Image();
    this.point.src = 'GFX/point.png';

    this.animator = animator;
    this.x = x;
    this.y = y;
    this.controll = controll;
    this.fromX = fromX;
    this.toX = toX;
    this.center = (this.fromX + this.toX) / 2;
    this.leftKey = leftKey;
    this.rightKey = rightKey;
    this.jumpKey = jumpKey;

    this.jumpState = MIN_JUMP;
    this.dir = 0;
    this.score = 0;
    this.mistake = 0;
    this.hits = 0;

    this.ballDest = null;

    this.width = this.animator.animation.clipWidth;
    this.height = this.animator.animation.clipHeight;

    this.jumpCoord = this.y - JUMP_LENGTH;
    this.jumpTriggerCoords = 0;

    this.handleEvents = function() { 
        this.animator.x = this.x;
        this.animator.y = this.y;

        this.animator.applyAnim();

        if (this.jumpState > MIN_JUMP) {
            this.y -= this.jumpState;
            this.jumpState -= 1;
        }

        if (this.jumpState > MIN_JUMP) {
            animator.switchAnim(JUMPING);
        } else if (this.dir !== 0) {
            animator.switchAnim(RUNNING);
        } else {
            animator.switchAnim(IDLE);
        }

        this.controlls();

        if (this.x > this.fromX && this.dir < 0 || this.x + this.width < this.toX && this.dir > 0) {
            this.x += this.dir;
        }
    }

    this.controllsHuman = function() {
        if (this.controll === KEYBOARD && this.jumpState === MIN_JUMP) {
            if (keystates[this.leftKey]) {
            this.dir = -4;
            } else if (keystates[this.rightKey]) {
                this.dir = 4;
            } else {
                this.dir = 0;
            }
            if (keystates[this.jumpKey]) {
                this.jump();
            }
        }
    }

    this.controllsAI = function() {
        // Check if the ball is on the AI's side
        if (inGame.ball.x + inGame.BallAnim.clipWidth/2 > this.fromX && inGame.ball.x + inGame.BallAnim.clipWidth/2 < this.toX) { // Adjust condition based on side
            // Calculate where the ball will fall and the correct dumpling area to hit
            var predictedLanding = this.predictBallLanding();

            predictedLanding -= this.calculateHitAreaOffset(predictedLanding);

            // Move the dumpling towards the predicted landing position
            this.moveTowards(predictedLanding);

            // Check if we need to jump
            if (inGame.ball.dy === 0 && this.x === predictedLanding && this.jumpState === MIN_JUMP) {
                this.jump();
            } else {
                var timeToReachPlayer = (this.y - inGame.ball.y - inGame.BallAnim.clipHeight) / inGame.ball.dy;
                if (timeToReachPlayer > 0 && timeToReachPlayer < MAX_JUMP / 2 && this.jumpState === MIN_JUMP) {
                    this.jump();
                }
            }

            // Adjust the ball's direction based on where it hits the dumpling
            //this.adjustHitPosition(predictedLanding.hitArea);
        } else {
            // Move to center if the ball is on the other side
            this.moveTowards(this.center);
        }
    }

    this.jump = function() {
        this.jumpState = MAX_JUMP;
    }

    this.moveTowards = function(targetX) {
        // Add a random factor to the moving
        var x = targetX !== this.center ? Math.floor(Math.random() * 4) - 2 : 0;
        // Move the player towards the target x position
        if (this.x < targetX - MOVE_SPEED) {
            this.dir = MOVE_SPEED;
        } else if (this.x > targetX + MOVE_SPEED) {
            this.dir = -MOVE_SPEED;
        } else {
            this.dir = 0;
            this.x = targetX + x;
        }
    }

    this.predictBallLanding = function() {
        // Predict the x-coordinate where the ball will land on the AI's side
        if (inGame.ball.dy === 0) {
            return inGame.ball.x + inGame.BallAnim.clipWidth / 2;
        }

        var timeToReachJumpHeight = (this.y - inGame.ball.y - inGame.BallAnim.clipHeight) / inGame.ball.dy; // Time for the ball to reach the player's y position during the jump
        var predictedX = inGame.ball.x + inGame.BallAnim.clipWidth / 2 + inGame.ball.dx * timeToReachJumpHeight; // Calculate predicted x landing position

        // Apply wall bounce correction recursively
        predictedX = this.handleWallBounces(predictedX);

        return predictedX;
    }

    this.handleWallBounces = function(predictedX) {
        // Calculate bouncing between the walls recursively
        // While the predicted X is outside of bounds, reflect it
        if (predictedX < this.fromX) {
            var overshoot = this.fromX - predictedX;
            predictedX = this.fromX + overshoot;
            predictedX = this.handleWallBounces(predictedX);  // Handle the next bounce
        } else if (predictedX > this.toX) {
            var overshoot = predictedX - this.toX;
            predictedX = this.toX - overshoot;
            predictedX = this.handleWallBounces(predictedX);  // Handle the next bounce
        }

        return predictedX;
    }

    this.calculateHitAreaOffsetRight = function(predictedX) {
        if (predictedX > this.toX - 60) {
            return 85;
        }
        return 0;
    }

	this.calculateHitAreaOffsetLeft = function(predictedX) {
        if (predictedX < this.fromX + 60) {
            return -25;
        }
        return 65;
    }

	this.defineControlls = function(controll) {
		this.controll = controll;
		this.controlls = this.controll === COMPUTER ? this.controllsAI : this.controllsHuman;		
	}

	this.resetPlayer = function() {
		this.hits = 0;
		this.score = 0;
	}

	this.calculateHitAreaOffset = this.fromX < line.x ? this.calculateHitAreaOffsetLeft : this.calculateHitAreaOffsetRight;
}

