        actions, actionToInputsMappings, entityPropertyNamesToProcess);
    }
    initialize(uwpe) {
        super.initialize(uwpe);
        var conversationDefnName = "Talk_ConversationsAll";
        var talker = Talker.fromConversationDefnName(conversationDefnName);
        talker.talk(uwpe);
    }
}

