ardilla[1].lives:=4;
ardilla[2].lives:=4;
ardilla[1].coins:=0;
ardilla[2].coins:=0;
ardilla[1].mode:=0;
ardilla[2].mode:=0;

quito:=false;

flp:=0;
if playlevel=28 then playlevel:=1;
repeat
racemode:=false;
key[123]:=false;
