MSG(20,50,min+' mins '+sec+' segs '+fr+' cent');
if (givemeallmili(ardilla[1].racestatus.min,
                  ardilla[1].racestatus.sec,
                  ardilla[1].racestatus.frac)<
   givemeallmili(hiscore[nivelz].min,
