                                  quito:=true;
                                  i:=5;
                                  end;
inc(i);
until i>5;
co1:=0;
co2:=0;

if not quito then begin
ReadPcxp('results.pcx',pag2^[0]);
{copyscr2;}

   for i:=1 to 5 do begin
       case res[i] of
       1:inc( co1);
       2:inc( co2);
       3:begin
         inc( co1);
         inc( co2);
         end;
       end;
   end;
