end;

Begin
ReadPCxp('stf.pcx'{,@Pag2^[0]},pag2^[0]);
bak^:=Pag2^;
i:=1;
Repeat
                       fillchar(pag2^[0],64000,0);
                       for j:=0 to 127 do fillchar(pag2^[63+j,0],320,128+j+random(2));
