__ASM__ __SAVE_DS__ PubStatus(
    __REG__(d0, struct PubBlock *pblock),
    __REG__(a6, struct HotLinksBase *base))
{
    struct HLPrivateBase *pb;
    struct HLPBCtx *ctx;
    struct HLCatalogEntry *ce;

    pb = HLGetPrivate(base);
    ctx = HLPBCtxFromBlock(pblock);
    if (ctx == NULL) {
