		{
			cout << AM->argtypename[AM->ARGTYPE[AM->CHAN][AM->PROGPOINTER[AM->CHAN]][TT]] << AM->COMMAND[AM->CHAN][AM->PROGPOINTER[AM->CHAN]][TT];
			if ( TT<AM->NUMARGS[AM->CHAN][(AM->PROGPOINTER[AM->CHAN])] )
