			cout << AM->strin[AM->CHAN][AM->PROGPOINTER[AM->CHAN]][TT];
			if ( TT<AM->NUMARGS[AM->CHAN][(AM->PROGPOINTER[AM->CHAN])] )
				cout << ", ";
